    var `port`: kotlin.UShort, 
    var `nonce`: kotlin.ByteArray
) {
    
    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeAnnouncementData: FfiConverterRustBuffer<AnnouncementData> {
    override fun read(buf: ByteBuffer): AnnouncementData {
        return AnnouncementData(
            FfiConverterByteArray.read(buf),
            FfiConverterByteArray.read(buf),
            FfiConverterUShort.read(buf),
            FfiConverterByteArray.read(buf),
        )
    }

    override fun allocationSize(value: AnnouncementData) = (
            FfiConverterByteArray.allocationSize(value.`fingerprintPrefix`) +
            FfiConverterByteArray.allocationSize(value.`ipv4`) +
            FfiConverterUShort.allocationSize(value.`port`) +
