/**
 * Things that can go wrong, reported to Kotlin as an exception.
 */
sealed class FlickException: kotlin.Exception() {
    
    class WrongLength(
        
        val `len`: kotlin.UInt
        ) : FlickException() {
        override val message
            get() = "len=${ `len` }"
    }
    
    class BadField(
        ) : FlickException() {
        override val message
            get() = ""
    }
    
    class Failed(
        
        val `message`: kotlin.String
        ) : FlickException() {
        override val message
            get() = "message=${ `message` }"
    }
    

    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<FlickException> {
        override fun lift(error_buf: RustBuffer.ByValue): FlickException = FfiConverterTypeFlickError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeFlickError : FfiConverterRustBuffer<FlickException> {
    override fun read(buf: ByteBuffer): FlickException {
        

        return when(buf.getInt()) {
            1 -> FlickException.WrongLength(
                FfiConverterUInt.read(buf),
                )
            2 -> FlickException.BadField()
            3 -> FlickException.Failed(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: FlickException): ULong {
        return when(value) {
            is FlickException.WrongLength -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterUInt.allocationSize(value.`len`)
            )
            is FlickException.BadField -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is FlickException.Failed -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`message`)
            )
        }
    }

    override fun write(value: FlickException, buf: ByteBuffer) {
        when(value) {
            is FlickException.WrongLength -> {
                buf.putInt(1)
                FfiConverterUInt.write(value.`len`, buf)
                Unit
            }
            is FlickException.BadField -> {
                buf.putInt(2)
                Unit
            }
            is FlickException.Failed -> {
                buf.putInt(3)
                FfiConverterString.write(value.`message`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}



/**
 * What this phone must do to reach the one it heard.
 */
sealed class LinkPlanData {
    
    /**
     * Already on the same network, nothing to do.
     */
    object SameNetwork : LinkPlanData()
    
    
    /**
     * Create a Wi-Fi Direct group with this name and password.
     */
    data class CreateGroup(
        val `ssid`: kotlin.String, 
        val `passphrase`: kotlin.String) : LinkPlanData() {
        companion object
    }
    
    /**
     * Join the Wi-Fi Direct group the other phone creates.
     */
    data class JoinGroup(
        val `ssid`: kotlin.String, 
        val `passphrase`: kotlin.String) : LinkPlanData() {
        companion object
    }
    

    
    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeLinkPlanData : FfiConverterRustBuffer<LinkPlanData>{
    override fun read(buf: ByteBuffer): LinkPlanData {
        return when(buf.getInt()) {
            1 -> LinkPlanData.SameNetwork
            2 -> LinkPlanData.CreateGroup(
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                )
            3 -> LinkPlanData.JoinGroup(
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: LinkPlanData) = when(value) {
        is LinkPlanData.SameNetwork -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is LinkPlanData.CreateGroup -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`ssid`)
                + FfiConverterString.allocationSize(value.`passphrase`)
            )
        }
        is LinkPlanData.JoinGroup -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`ssid`)
                + FfiConverterString.allocationSize(value.`passphrase`)
            )
        }
    }

    override fun write(value: LinkPlanData, buf: ByteBuffer) {
        when(value) {
            is LinkPlanData.SameNetwork -> {
                buf.putInt(1)
                Unit
            }
            is LinkPlanData.CreateGroup -> {
                buf.putInt(2)
                FfiConverterString.write(value.`ssid`, buf)
                FfiConverterString.write(value.`passphrase`, buf)
                Unit
            }
            is LinkPlanData.JoinGroup -> {
                buf.putInt(3)
                FfiConverterString.write(value.`ssid`, buf)
                FfiConverterString.write(value.`passphrase`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}





