                Unit
            }
            is TransferEvent.Finished -> {
                buf.putInt(4)
                FfiConverterString.write(value.`sessionId`, buf)
                FfiConverterBoolean.write(value.`ok`, buf)
                Unit
            }
            is TransferEvent.Declined -> {
