public object FfiConverterOptionalTypeAnnouncementData: FfiConverterRustBuffer<AnnouncementData?> {
    override fun read(buf: ByteBuffer): AnnouncementData? {
        if (buf.get().toInt() == 0) {
            return null
        }
        return FfiConverterTypeAnnouncementData.read(buf)
    }

    override fun allocationSize(value: AnnouncementData?): ULong {
        if (value == null) {
            return 1UL
        } else {
            return 1UL + FfiConverterTypeAnnouncementData.allocationSize(value)
        }
    }

    override fun write(value: AnnouncementData?, buf: ByteBuffer) {
        if (value == null) {
            buf.put(0)
        } else {
            buf.put(1)
            FfiConverterTypeAnnouncementData.write(value, buf)
        }
    }
}




